// Full path data — all points connected, no filtering
const CHART_W = 3000;
const CHART_H = 500;

function buildPath(pts: number[][]): string {
  return pts
    .map((p, i) => {
      const x = (p[0] / 100) * CHART_W;
      const y = (p[1] / 100) * CHART_H;
      return `${i === 0 ? "M" : "L"} ${x.toFixed(1)} ${y.toFixed(1)}`;
    })
    .join(" ");
}

const stablePts = [
  [0, 25],
  [15, 28],
  [30, 22],
  [45, 30],
  [60, 26],
  [75, 24],
  [90, 28],
  [100, 25],
];

const volatilePts = [
  [0, 30],
  [15, 70],
  [30, 20],
  [45, 80],
  [60, 35],
  [75, 75],
  [90, 15],
  [100, 65],
];

const fullStablePath = buildPath(stablePts);
const fullVolatilePath = buildPath(volatilePts);

// Approximate total path length for dashoffset technique
const STABLE_LENGTH = 3100;

const Phase3: React.FC = () => {
  const frame = useCurrentFrame();
  const { fps: f } = useVideoConfig();

  const cardProg = spring({ frame, fps: f, delay: 10, config: { damping: 200 } });

