    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });

  const statProg = spring({ frame, fps: f, delay: 120, config: { damping: 200 } });
  const badge1Prog = spring({ frame, fps: f, delay: 130, config: { damping: 200 } });
  const badge2Prog = spring({ frame, fps: f, delay: 145, config: { damping: 200 } });
  const pillProg = spring({ frame, fps: f, delay: 160, config: { damping: 200 } });

  const gridLines = [0, 25, 50, 75, 100];
  const xLabels = ["Wk 1", "Wk 3", "Wk 5", "Wk 7", "Wk 9", "Wk 12"];

  // Clip rect width for volatile line reveal
  const clipWidth = CHART_W * drawProg;

  return (
    <AbsoluteFill style={{ fontFamily: "'Inter', sans-serif" }}>
      <Background />
      <SafeZone>
        <div
          style={{
            width: "100%",
            height: "100%",
            display: "flex",
            alignItems: "center",
            justifyContent: "center",
          }}
        >
          <div
            style={{
              width: "100%",
              backgroundColor: COLORS.card,
              border: `2px solid ${COLORS.cardBorder}`,
              borderRadius: 32,
              padding: "56px 72px",
              display: "flex",
              flexDirection: "column",
              gap: 40,
              opacity: cardProg,
              transform: `translateY(${interpolate(
                cardProg,
                [0, 1],
                [50, 0]
              )}px) scale(${interpolate(cardProg, [0, 1], [0.92, 1])})`,
            }}
          >
            {/* Header */}
            <div
              style={{
                color: COLORS.muted,
                fontSize: 28,
                fontWeight: 700,
                textTransform: "uppercase",
                letterSpacing: "0.08em",
              }}
            >
              AI CITATION VOLATILITY — 12-WEEK WINDOW
            </div>

            {/* Chart SVG — lines + grid only, no overlaid text */}
            <svg
              width={CHART_W}
              height={CHART_H + 60}
              viewBox={`0 0 ${CHART_W} ${CHART_H + 60}`}
              style={{ width: "100%", height: "auto" }}
            >
              <defs>
                {/* Clip path for volatile (dashed) line progressive reveal */}
                <clipPath id="volatileReveal">
                  <rect
                    x={0}
                    y={0}
                    width={clipWidth}
                    height={CHART_H + 10}
                  />
                </clipPath>
              </defs>

              {/* Grid lines */}
              {gridLines.map((pct) => (
                <line
                  key={pct}
                  x1={0}
                  y1={(pct / 100) * CHART_H}
                  x2={CHART_W}
                  y2={(pct / 100) * CHART_H}
                  stroke="rgba(255,255,255,0.05)"
                  strokeWidth={2}
                />
              ))}

              {/* Stable line — dashoffset technique for smooth reveal */}
              <path
                d={fullStablePath}
                stroke={COLORS.blue}
                strokeWidth={8}
                strokeLinecap="round"
                strokeLinejoin="round"
                fill="none"
                strokeDasharray={STABLE_LENGTH}
                strokeDashoffset={STABLE_LENGTH * (1 - drawProg)}
              />

              {/* Volatile line — clip mask for smooth reveal, keeps dash pattern */}
              <g clipPath="url(#volatileReveal)">
                <path
                  d={fullVolatilePath}
                  stroke={COLORS.amber}
                  strokeWidth={6}
                  strokeLinecap="round"
                  strokeLinejoin="round"
                  strokeDasharray="24 12"
                  fill="none"
                />
              </g>

              {/* X-axis labels */}
              {xLabels.map((label, i) => {
                const xPct = (i / (xLabels.length - 1)) * 100;
                return (
                  <text
                    key={label}
                    x={(xPct / 100) * CHART_W}
                    y={CHART_H + 48}
                    textAnchor="middle"
                    fill={COLORS.muted}
                    fontSize={28}
                    fontWeight={600}
                    fontFamily="Inter, sans-serif"
                  >
                    {label}
                  </text>
                );
              })}
            </svg>

            {/* Stat row — between chart and annotation badges */}
            <div
              style={{
                display: "flex",
                alignItems: "center",
                justifyContent: "center",
                marginTop: 40,
                marginBottom: 32,
                opacity: statProg,
                transform: `translateY(${interpolate(
