                  lineHeight: 1,
                }}
              >
                40–60%
              </div>
              <div
                style={{
                  width: 3,
                  height: 60,
                  backgroundColor: "rgba(251,191,36,0.3)",
                  borderRadius: 2,
                  marginLeft: 36,
                  marginRight: 36,
                  flexShrink: 0,
                }}
              />
              <div
                style={{
                  color: COLORS.muted,
                  fontSize: 32,
                  fontWeight: 600,
                  maxWidth: 400,
                  lineHeight: 1.4,
                }}
              >
                of citations change month to month
              </div>
            </div>

            {/* Annotation badges */}
            <div
              style={{ display: "flex", gap: 48, alignItems: "center" }}
            >
              <div
                style={{
                  backgroundColor: "rgba(0,170,255,0.1)",
                  border: `1.5px solid rgba(0,170,255,0.3)`,
                  borderRadius: 16,
                  padding: "20px 40px",
                  display: "flex",
                  alignItems: "center",
                  gap: 16,
                  opacity: badge1Prog,
                  transform: `translateY(${interpolate(
                    badge1Prog,
                    [0, 1],
                    [20, 0]
                  )}px)`,
                }}
              >
                <div
                  style={{
                    width: 40,
                    height: 6,
                    backgroundColor: COLORS.blue,
                    borderRadius: 3,
                    flexShrink: 0,
                  }}
                />
                <span
                  style={{
                    color: COLORS.blue,
                    fontSize: 30,
                    fontWeight: 700,
                  }}
                >
                  Stable sources: ~30% of citations
                </span>
              </div>

